style.css:
@-moz-document domain("gemini.google.com") {
/* =========================================
       1. 全局色彩与变量定义 (莫兰迪柔和色系)
       ========================================= */
    :root {
        /* 背景色 */
        --gemini-bg-main: #F8F9FA !important;       /* 主背景：珍珠灰白 */
        --gemini-bg-sidebar: #F0F2F5 !important;    /* 侧边栏：极浅灰 */
        
        /* 对话框颜色 */
        --gemini-bubble-ai: #FFFFFF !important;     /* AI 回复：纯白底色 */
        --gemini-bubble-user: #EBF1F5 !important;   /* 用户回复：极浅的雾霾蓝 */
        --gemini-input-bg: #FFFFFF !important;      /* 输入框底色 */
        
        /* 文本颜色 */
        --gemini-text-primary: #3C4043 !important;  /* 主标题/正文：柔和深灰 */
        --gemini-text-secondary: #70757A !important;/* 次要文本：中灰 */
        
        /* 视觉修饰 */
        --gemini-radius-large: 24px !important;     /* 大圆角 */
        --gemini-radius-medium: 16px !important;    /* 中圆角 */
        --gemini-shadow-soft: 0 8px 24px rgba(0, 0, 0, 0.04) !important; /* 弥散阴影 */
        --gemini-border-soft: 1px solid rgba(0, 0, 0, 0.03) !important;
    }

    /* =========================================
       2. 全局排版与背景重置
       ========================================= */
    body, main, #app-root, .mdc-drawer {
        background-color: var(--gemini-bg-main) !important;
        color: var(--gemini-text-primary) !important;
        font-family: "Inter", -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Roboto, sans-serif !important;
        letter-spacing: 0.3px !important;
    }

    /* 侧边栏专属背景 */
    mat-sidenav, .mdc-drawer__content {
        background-color: var(--gemini-bg-sidebar) !important;
        border-right: none !important;
    }

    /* =========================================
       3. 对话区域美化 (核心视觉)
       ========================================= */
    
    /* 隐藏生硬的分割线 */
    hr {
        border-color: rgba(0,0,0,0.05) !important;
    }

    /* 用户发送的消息气泡 */
    .user-message, 
    [data-test-id="user-message"] {
        background-color: var(--gemini-bubble-user) !important;
        border-radius: var(--gemini-radius-large) !important;
        padding: 16px 24px !important;
        color: var(--gemini-text-primary) !important;
        box-shadow: none !important;
        margin-bottom: 24px !important;
    }

    /* AI 回复的消息气泡/区域 */
    .model-response, 
    [data-test-id="model-message"] {
        background-color: var(--gemini-bubble-ai) !important;
        border-radius: var(--gemini-radius-large) !important;
        padding: 24px 32px !important;
        box-shadow: var(--gemini-shadow-soft) !important;
        border: var(--gemini-border-soft) !important;
        margin-bottom: 32px !important;
        line-height: 1.7 !important; /* 增加行高，提升阅读呼吸感 */
    }

    /* 代码块美化：降低对比度，不刺眼 */
    pre, code, .code-block {
        background-color: #282C34 !important;
        border-radius: 12px !important;
        font-family: "Fira Code", "JetBrains Mono", monospace !important;
        border: none !important;
        box-shadow: inset 0 2px 8px rgba(0,0,0,0.2) !important;
    }

    /* =========================================
       4. 底部输入框美化
       ========================================= */
    /* 输入框外部容器 */
    .chat-input-container, 
    [data-test-id="chat-input-wrapper"] {
        background: transparent !important;
        border-top: none !important;
        padding-bottom: 24px !important;
    }

    /* 实际输入区域 */
    textarea, 
    .chat-input-textarea {
        background-color: var(--gemini-input-bg) !important;
        border-radius: var(--gemini-radius-large) !important;
        box-shadow: 0 4px 16px rgba(0,0,0,0.06), 0 0 0 1px rgba(0,0,0,0.02) !important;
        padding: 16px 24px !important;
        color: var(--gemini-text-primary) !important;
        transition: box-shadow 0.3s ease !important;
    }

    /* 输入框聚焦时的优雅发光效果 */
    textarea:focus, 
    .chat-input-textarea:focus {
        box-shadow: 0 6px 24px rgba(100, 150, 200, 0.15), 0 0 0 2px rgba(137, 168, 178, 0.3) !important;
        outline: none !important;
    }

    /* 发送按钮悬浮效果 */
    button[aria-label="Send"], 
    .send-button {
        color: #89A8B2 !important; /* 优雅的灰蓝色 */
        transition: transform 0.2s ease, color 0.2s ease !important;
    }
    button[aria-label="Send"]:hover, 
    .send-button:hover {
        transform: scale(1.05) !important;
        color: #6B8A94 !important;
    }

    /* =========================================
       5. 滚动条美化
       ========================================= */
    ::-webkit-scrollbar {
        width: 8px !important;
        height: 8px !important;
    }
    ::-webkit-scrollbar-track {
        background: transparent !important;
    }
    ::-webkit-scrollbar-thumb {
        background: #D4D8DB !important;
        border-radius: 10px !important;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #BFC4C8 !important;
    }
}
